   506	                throw new Xjt45Exception(Xjt45ErrorCode.INVALID_PAYMENT_STATUS,
   507	                        "현재 상태(" + payment.getStatus() + ")에서 " + newStatus + " 상태로 변경할 수 없습니다.");
   508	            }
